// features/tracking/trackingSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface TrackedEvent {
  id: string;
  type: string;
  timestamp: number;
  metadata?: Record<string, any>;
  route?: string;
  duration?: number;
  error?: string;
}

interface TrackingState {
  events: TrackedEvent[];
  pageViews: string[];
  routeHistory: string[];
  featureUsage: Record<string, number>;
  goalsCompleted: string[];
  currentSessionId: string | null;
  userId: string | null;
  flowProgress: Record<string, number>;
  latencyMap: Record<string, number>;
  diagnostics: TrackedEvent[];
  isTrackingEnabled: boolean;
  environment: 'prod' | 'dev' | 'staging';
  platform: 'web' | 'mobile' | 'desktop';
  activeFlow: string | null;
}

const initialState: TrackingState = {
  events: [],
  pageViews: [],
  routeHistory: [],
  featureUsage: {},
  goalsCompleted: [],
  currentSessionId: null,
  userId: null,
  flowProgress: {},
  latencyMap: {},
  diagnostics: [],
  isTrackingEnabled: true,
  environment: 'prod',
  platform: 'web',
  activeFlow: null,
};

const trackingSlice = createSlice({
  name: 'tracking',
  initialState,
  reducers: {
    // 📈 Events and views
    logEvent: (s, a: PayloadAction<TrackedEvent>) => {
      s.events.push(a.payload);
      if (a.payload.error) s.diagnostics.push(a.payload);
    },
    logPageView: (s, a: PayloadAction<string>) => {
      s.pageViews.push(a.payload);
      s.routeHistory.push(a.payload);
    },

    // 🛠️ Feature counters
    incrementFeatureUsage: (s, a: PayloadAction<string>) => {
      s.featureUsage[a.payload] = (s.featureUsage[a.payload] ?? 0) + 1;
    },

    // 🎯 Goals and flows
    completeGoal: (s, a: PayloadAction<string>) => {
      if (!s.goalsCompleted.includes(a.payload)) s.goalsCompleted.push(a.payload);
    },
    updateFlowProgress: (s, a: PayloadAction<{ flowId: string; step: number }>) => {
      s.flowProgress[a.payload.flowId] = a.payload.step;
    },
    setActiveFlow: (s, a: PayloadAction<string | null>) => {
      s.activeFlow = a.payload;
    },

    // ⏱️ Timing and latency
    setLatencyMetric: (s, a: PayloadAction<{ key: string; value: number }>) => {
      s.latencyMap[a.payload.key] = a.payload.value;
    },

    // 🔐 Session/User info
    setSessionId: (s, a: PayloadAction<string | null>) => {
      s.currentSessionId = a.payload;
    },
    setUserId: (s, a: PayloadAction<string | null>) => {
      s.userId = a.payload;
    },

    // 🧪 Diagnostics
    addDiagnosticEvent: (s, a: PayloadAction<TrackedEvent>) => {
      s.diagnostics.push(a.payload);
    },
    clearDiagnostics: (s) => {
      s.diagnostics = [];
    },

    // ⚙️ Settings
    toggleTracking: (s) => {
      s.isTrackingEnabled = !s.isTrackingEnabled;
    },
    setEnvironment: (s, a: PayloadAction<TrackingState['environment']>) => {
      s.environment = a.payload;
    },
    setPlatform: (s, a: PayloadAction<TrackingState['platform']>) => {
      s.platform = a.payload;
    },

    // 🧼 Reset
    resetTrackingState: () => initialState,
  }
});
